INSERT INTO `medical_history` (`id`, `patient_id`, `record_date`, `record_type`, `title`, `doctor_id`, `doctor_name`, `facility`, `severity`, `notes`, `created_at`) VALUES
  (1, 1, '2026-04-16 18:30:00', 'Diagnosis', 'Essential (Primary) Hypertension Stage 1', 2, 'Dr. Marcus Vance', 'Heart & Vascular Pavilion', 'Moderate', 'Resting BP 144/92 mmHg over consecutive visits. Initiated lifestyle counseling and antihypertensive medication.', '2026-04-17 03:20:00'),
  (2, 1, '2026-06-25 18:30:00', 'Visit', 'Cardiology Follow-up & ECG', 2, 'Dr. Marcus Vance', 'Cardiology Clinic B', 'Routine', 'Normal sinus rhythm. BP improved to 126/82 mmHg on Lisinopril 10mg daily. No peripheral edema noted.', '2026-06-26 03:20:00'),
  (3, 1, '2026-09-03 18:30:00', 'Vaccination', 'Annual Quadrivalent Influenza Vaccine', 3, 'Dr. Sarah Chen', 'MediVault Community Health Center', 'Routine', 'Administered 0.5 mL IM left deltoid. No acute reaction within 15 minutes observation.', '2026-09-04 03:20:00'),
  (4, 1, '2026-10-08 18:30:00', 'Diagnosis', 'Tension-Type Migraine Headache', 3, 'Dr. Sarah Chen', 'Neurology & Wellness Suites', 'Mild', 'Recurrent bilateral throbbing headaches exacerbated by screen fatigue. Prescribed sleep hygiene protocol.', '2026-10-09 03:20:00'),
  (5, 2, '2026-02-15 18:30:00', 'Diagnosis', 'Type 2 Diabetes Mellitus with Mild Neuropathy', 3, 'Dr. Sarah Chen', 'Diabetes & Endocrinology Institute', 'Moderate', 'HbA1c elevated at 8.4%. Patient reports mild tingling sensations in bilateral lower extremities.', '2026-02-16 03:20:00'),
  (6, 2, '2026-05-06 18:30:00', 'Surgery', 'Percutaneous Coronary Intervention (Stent Placement in LAD)', 2, 'Dr. Marcus Vance', 'Cardiac Cath Lab, MediVault Memorial', 'Critical', 'Successfully deployed drug-eluting stent in proximal left anterior descending artery. Uncomplicated recovery.', '2026-05-07 03:20:00'),
  (7, 2, '2026-09-13 18:30:00', 'Visit', 'Post-PCI Cardiac Evaluation', 2, 'Dr. Marcus Vance', 'Cardiology Suite 402', 'Routine', 'Patient tolerating dual antiplatelet therapy well. Stress echo negative for ischemia.', '2026-09-14 03:20:00'),
  (8, 3, '2026-04-26 18:30:00', 'Diagnosis', 'Moderate Persistent Bronchial Asthma Exacerbation', 4, 'Dr. Raj Patel', 'Pulmonary Medicine Dept', 'Severe', 'Patient presented with wheezing and nocturnal dyspnea triggered by seasonal tree pollen. Peak flow at 65% predicted.', '2026-04-27 03:20:00'),
  (9, 3, '2026-08-04 18:30:00', 'Visit', 'Spirometry and Pulmonary Function Test', 4, 'Dr. Raj Patel', 'Respiratory Therapy Lab', 'Routine', 'Post-bronchodilator FEV1 improved by 18%. Inhaled corticosteroid dosage adjusted.', '2026-08-05 03:20:00'),
  (10, 6, '2026-03-07 18:30:00', 'Hospitalization', 'Acute COPD Exacerbation with Hypoxemia', 4, 'Dr. Raj Patel', 'Critical Care Inpatient Unit', 'Critical', 'Admitted for oxygen therapy, IV methylprednisolone, and nebulized bronchodilators for 4 days. Discharged stable.', '2026-03-08 03:20:00'),
  (11, 6, '2026-07-15 18:30:00', 'Visit', 'Pulmonary Rehabilitation Assessment', 4, 'Dr. Raj Patel', 'Rehab Medicine Annex', 'Moderate', 'Completed 6-minute walk test (380 meters). Supplemental oxygen ordered at 2 L/min during exertion.', '2026-07-16 03:20:00'),
  (12, 10, '2026-05-16 18:30:00', 'Diagnosis', 'Paroxysmal Atrial Fibrillation', 2, 'Dr. Marcus Vance', 'Arrhythmia Center', 'Severe', 'Holter monitor confirmed episodes of AFib with rapid ventricular response up to 138 bpm.', '2026-05-17 03:20:00'),
  (13, 12, '2026-07-25 18:30:00', 'Diagnosis', 'Congestive Heart Failure (NYHA Class II)', 2, 'Dr. Marcus Vance', 'Heart Failure Care Clinic', 'Severe', 'Echocardiogram reveals reduced ejection fraction of 42%. Mild trace ankle edema.', '2026-07-26 03:20:00'),
  (14, 16, '2026-09-18 18:30:00', 'Visit', 'Athletic Physical & Pulmonary Clearance', 4, 'Dr. Raj Patel', 'Sports Medicine Annex', 'Routine', 'Spirometry normal. Cleared for intercollegiate track with Albuterol premedication.', '2026-09-19 03:20:00'),
  (15, 22, '2026-10-03 18:30:00', 'Diagnosis', 'Peripheral Artery Disease Evaluation', 2, 'Dr. Marcus Vance', 'Vascular Diagnostic Suite', 'Moderate', 'Ankle-brachial index measured at 0.78 on the right lower extremity. Started Cilostazol.', '2026-10-04 03:20:00');
INSERT INTO `prescriptions` (`id`, `patient_id`, `doctor_id`, `medication_name`, `dosage`, `frequency`, `duration`, `start_date`, `end_date`, `instructions`, `status`, `notes`, `created_at`, `updated_at`) VALUES
  (1, 1, 2, 'Lisinopril', '10 mg', 'Once daily in the morning', '90 days', '2026-04-16 18:30:00', NULL, 'Take with or without food. Monitor blood pressure weekly.', 'Completed', 'Initial titration for hypertension.', '2026-04-16 23:00:00', '2026-11-03 11:21:48'),
  (2, 1, 2, 'Lisinopril', '20 mg', 'Once daily in the morning', '180 days', '2026-07-15 18:30:00', NULL, 'Maintain daily morning dose. Refill before expiration.', 'Active', 'Dose increased for optimal target systolic control (< 130 mmHg).', '2026-07-15 23:00:00', '2026-11-03 11:21:48'),
  (3, 1, 3, 'Sumatriptan', '50 mg', 'As needed at migraine onset', '30 days', '2026-10-08 18:30:00', NULL, 'Take single dose at earliest sign of migraine aura. Do not exceed 200mg in 24 hours.', 'Active', 'Abortive therapy for acute migraine flares.', '2026-10-08 23:00:00', '2026-11-03 11:21:48'),
  (4, 2, 3, 'Metformin Hydrochloride ER', '1000 mg', 'Twice daily with meals', '180 days', '2026-02-25 18:30:00', NULL, 'Take with breakfast and dinner to reduce GI upset.', 'Completed', 'First-line glycemic control.', '2026-02-25 23:00:00', '2026-11-03 11:21:48'),
  (5, 2, 2, 'Clopidogrel (Plavix)', '75 mg', 'Once daily', '365 days', '2026-05-16 18:30:00', NULL, 'Take consistently every morning. Do not discontinue without consulting cardiologist.', 'Active', 'Antiplatelet therapy post-stent placement.', '2026-05-16 23:00:00', '2026-11-03 11:21:48'),
  (6, 2, 2, 'Atorvastatin Calcium', '40 mg', 'Once daily at bedtime', '180 days', '2026-05-16 18:30:00', NULL, 'Avoid grapefruit consumption while on this medication.', 'Active', 'High-intensity statin regimen.', '2026-05-16 23:00:00', '2026-11-03 11:21:48'),
  (7, 3, 4, 'Fluticasone Propionate / Salmeterol', '250/50 mcg', '1 inhalation twice daily', '90 days', '2026-08-09 18:30:00', NULL, 'Rinse mouth thoroughly with water after inhalation to prevent oral candidiasis.', 'Active', 'Controller maintenance for moderate asthma.', '2026-08-09 23:00:00', '2026-11-03 11:21:48'),
  (8, 3, 4, 'Albuterol Sulfate HFA Inhaler', '90 mcg/actuation', '1-2 puffs every 4-6 hours PRN', 'As needed', '2026-08-09 18:30:00', NULL, 'Use spacer device if available. Carry for sudden shortness of breath.', 'Active', 'Rescue bronchodilator.', '2026-08-09 23:00:00', '2026-11-03 11:21:48'),
  (9, 4, 3, 'Rosuvastatin (Crestor)', '10 mg', 'Once daily in the evening', '90 days', '2026-07-15 18:30:00', NULL, 'Take with or without food. Report any unexplained muscle aches.', 'Completed', 'Targeting LDL < 100 mg/dL.', '2026-07-15 23:00:00', '2026-11-03 11:21:48'),
  (10, 5, 3, 'Levothyroxine Sodium', '75 mcg', 'Once daily on empty stomach', '180 days', '2026-06-15 18:30:00', NULL, 'Take 30-60 minutes before breakfast with full glass of plain water.', 'Active', 'Thyroid hormone replacement.', '2026-06-15 23:00:00', '2026-11-03 11:21:48'),
  (11, 6, 4, 'Tiotropium Bromide (Spiriva)', '2.5 mcg', '2 inhalations once daily', '90 days', '2026-08-24 18:30:00', NULL, 'Inhale at same time each day.', 'Active', 'Long-acting anticholinergic for COPD.', '2026-08-24 23:00:00', '2026-11-03 11:21:48'),
  (12, 10, 2, 'Apixaban (Eliquis)', '5 mg', 'Twice daily', '180 days', '2026-05-21 18:30:00', NULL, 'Take morning and evening. Do not skip doses to maintain stroke protection.', 'Active', 'Oral anticoagulant.', '2026-05-21 23:00:00', '2026-11-03 11:21:48'),
  (13, 10, 2, 'Metoprolol Succinate ER', '50 mg', 'Once daily', '90 days', '2026-05-21 18:30:00', NULL, 'Swallow whole, do not crush or chew. Take with food.', 'Completed', 'Ventricular rate control.', '2026-05-21 23:00:00', '2026-11-03 11:21:48'),
  (14, 12, 2, 'Furosemide (Lasix)', '40 mg', 'Once daily in the morning', '60 days', '2026-09-18 18:30:00', NULL, 'Take early morning to prevent nocturia.', 'Active', 'Loop diuretic for volume overload management.', '2026-09-18 23:00:00', '2026-11-03 11:21:48'),
  (15, 20, 2, 'Omeprazole', '20 mg', 'Once daily before breakfast', '30 days', '2026-10-13 18:30:00', NULL, 'Take with water before morning meal.', 'Active', 'Proton pump inhibitor for reflux relief.', '2026-10-13 23:00:00', '2026-11-03 11:21:48'),
  (16, 22, 2, 'Cilostazol', '100 mg', 'Twice daily 30 min before meals', '90 days', '2026-10-03 18:30:00', NULL, 'Take on empty stomach.', 'Active', 'Vasodilator for intermittent claudication.', '2026-10-03 23:00:00', '2026-11-03 11:21:48'),
  (17, 1, 2, 'Propranolol', '40 mg', 'Once daily', '14 days', '2026-08-04 18:30:00', NULL, 'Discontinued due to mild bradycardia.', 'Cancelled', 'Switched to Lisinopril titration.', '2026-08-04 23:00:00', '2026-11-03 11:21:48');
